type Decision = { allowed: true } | { allowed: false; reason: string };
type Policy = (ctx: SecurityContext, a: Action, r: Resource) => Decision;

const guard = (policy: Policy) =>
  (req: Request, res: Response, next: NextFunction) => {
    const ctx = req.securityContext;
    if (!ctx) return res.status(401).end();        // fail closed
    const d = policy(ctx, req.action, req.resource);
    if (!d.allowed) return res.status(403).json({ reason: d.reason });
    next();                                        // downstream code is rule-free
  };
