@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private authz: PolicyService) {}
  async canActivate(ctx: ExecutionContext): Promise<boolean> {
    const roles = this.reflector.get(Roles, ctx.getHandler());
    const user = ctx.switchToHttp().getRequest().user;
    return this.authz.decide(user, roles ?? []);   // policy = PolicyService
  }
}
@UseGuards(RolesGuard) @Roles(['admin']) @Post() create() {}
